    font-size: 0.875rem;
}

.alert-danger {
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    color: #842029;
}

/* Work Entry & Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #eee;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
    font-size: 1rem;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #dc3545;
    font-weight: 600;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #eee;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
}

.review-details {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    font-size: 0.875rem;
}

.review-details dt {
    font-weight: 500;
    color: #6c757d;
}

.review-details dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
    margin-bottom: 0.5rem;
    font-size: 0.875rem;
}

.review-work-entry p {
    margin: 0.5rem 0 0;
    font-size: 0.8rem;
}

.text-muted {
    color: #6c757d;
    font-size: 0.8rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.875rem;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #198754;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.submission-confirmation h4 {
    color: #198754;
    margin-bottom: 1rem;
}

