.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #eee;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
}

.review-details {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    font-size: 0.875rem;
}

.review-details dt {
    font-weight: 500;
    color: #6c757d;
}

.review-details dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
    margin-bottom: 0.5rem;
    font-size: 0.875rem;
}

.review-work-entry p {
    margin: 0.5rem 0 0;
    font-size: 0.8rem;
}

.text-muted {
    color: #6c757d;
    font-size: 0.8rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.875rem;
}

